-- Idempotent: safe to run twice. User-created categories are never touched.

begin;

alter table categories add column if not exists description text;

-- 1. Renames (same row, new name).
update categories set name = 'City/Town Tax' where is_system and name = 'City/Township Tax' and kind = 'expense'
  and not exists (select 1 from categories t where t.is_system and t.name = 'City/Town Tax' and t.kind = 'expense');
update categories set name = 'Home Insurance' where is_system and name = 'Insurance' and kind = 'expense'
  and not exists (select 1 from categories t where t.is_system and t.name = 'Home Insurance' and t.kind = 'expense');
