  and not exists (select 1 from categories t where t.is_system and t.name = 'Trash/Recycling' and t.kind = 'expense');
update categories set name = 'Renovation/Improvements' where is_system and name = 'Capital Improvement' and kind = 'expense'
  and not exists (select 1 from categories t where t.is_system and t.name = 'Renovation/Improvements' and t.kind = 'expense');
