  and not exists (select 1 from categories t where t.is_system and t.name = 'Other Rental Income' and t.kind = 'income');

-- 2. Merges (move entries and rules, then drop the old row). Make sure each
--    target exists first; usually it already does, or a rename above made it.
select v.name, v.kind, v.scope, true
  from (values
    ('Water & Sewer', 'expense', 'both'),
    ('Other Expense', 'expense', 'both'),
    ('Other Rental Income', 'income', 'property')
  ) as v(name, kind, scope)
 where not exists (select 1 from categories c where c.is_system and c.name = v.name and c.kind = v.kind);

-- Sewer → Water & Sewer
update expenses set category_id = (select id from categories where is_system and name = 'Water & Sewer' and kind = 'expense') where category_id = (select id from categories where is_system and name = 'Sewer' and kind = 'expense');
