delete from categories where is_system and name = 'Sewer' and kind = 'expense';

-- Parking → Other Rental Income
update expenses set category_id = (select id from categories where is_system and name = 'Other Rental Income' and kind = 'income') where category_id = (select id from categories where is_system and name = 'Parking' and kind = 'income');
